#include <algorithm>
#include <iostream>
#include <vector>

int maxHappyChildren(std::vector<int> greed, std::vector<int> sizes) {
    std::sort(greed.begin(), greed.end());
    std::sort(sizes.begin(), sizes.end());
    std::size_t child = 0;
    std::size_t cookie = 0;
    while (child < greed.size() && cookie < sizes.size()) {
        if (sizes[cookie] >= greed[child]) {
            child++;  // this child is happy, go on to the next one
        }
        cookie++;
    }
    return static_cast<int>(child);
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> greed(n);
    for (int i = 0; i < n; i++) {
        std::cin >> greed[i];
    }
    int m;
    std::cin >> m;
    std::vector<int> sizes(m);
    for (int i = 0; i < m; i++) {
        std::cin >> sizes[i];
    }
    std::cout << maxHappyChildren(greed, sizes) << "\n";
    return 0;
}

