package main

import (
	"fmt"
	"sort"
)

func maxHappyChildren(greed []int, sizes []int) int {
	sort.Ints(greed)
	sort.Ints(sizes)
	child, cookie := 0, 0
	for child < len(greed) && cookie < len(sizes) {
		if sizes[cookie] >= greed[child] {
			child++ // this child is happy, go on to the next one
		}
		cookie++
	}
	return child
}

func main() {
	var n int
	fmt.Scan(&n)
	greed := make([]int, n)
	for i := range greed {
		fmt.Scan(&greed[i])
	}
	var m int
	fmt.Scan(&m)
	sizes := make([]int, m)
	for i := range sizes {
		fmt.Scan(&sizes[i])
	}
	fmt.Println(maxHappyChildren(greed, sizes))
}

